def issue(key, title, problem, consequence, evidence, pages, middle, good):
    return {
        "id": key, "title": title, "problem": problem, "consequence": consequence,
        "evidence": evidence, "source": f"{SOURCE}, PDF viewer pages {pages}",
        "rubric": [
            "0 · Not addressed: the problem is confirmed and no response is defined.",
            "1 · Initial: the problem is identified, with an incomplete or informal response.",
            f"2 · Partly addressed: {middle}",
            f"3 · Well addressed: {good}",
            "4 · Fully addressed: level 3 is met across the agreed scope, with documented verification, an owner and a review plan appropriate to the project stage.",
        ],
    }


