def action(key, issue_id, title, kind, unit, low, high, annual, benefit, tradeoff, prerequisite):
    return {"id": key, "issue": issue_id, "title": title, "kind": kind,
            "unit": unit, "low": low, "high": high, "annual": annual,
            "benefit": benefit, "tradeoff": tradeoff, "prerequisite": prerequisite,
            "cost_basis": "Editable hackathon allowance, EUR excluding tax. Not a supplier quote or an official Nexity benchmark."}


